'use strict';
const test=require('node:test'),assert=require('node:assert/strict'),fs=require('node:fs'),path=require('node:path');
const D=require('../public/taipei-guide-data.js'),Guide=require('../public/taipei-guide.js');
// These totals were retrieved separately from CEC's city-level profiles, not
// generated by aggregating the public district bundle under test.
const audit=JSON.parse(fs.readFileSync(path.join(__dirname,'../research/taipei-districts/election-audit.json'),'utf8'));
const page=fs.readFileSync(path.join(__dirname,'../public/taipei.html'),'utf8');
const fields=['validVotes','invalidVotes','votesCast','eligibleVoters'];
const sorted=values=>[...values].sort();
const sum=(rows,key)=>rows.reduce((total,row)=>total+row[key],0);
const round2=value=>Math.round(value*100)/100;
const legislativeMapping={
  '松山區':[3,7],'信義區':[7],'大安區':[6],'中山區':[3],
  '中正區':[5,8],'大同區':[2],'萬華區':[5],'文山區':[8],
  '南港區':[4],'內湖區':[4],'士林區':[1,2],'北投區':[1]
};

test('Taipei guide retains every candidate and the complete valid-vote denominator',()=>{
  assert.deepEqual(sorted(D.elections.map(e=>e.id)),sorted(audit.elections.map(e=>e.id)));
  for(const election of D.elections){
    const verified=audit.elections.find(e=>e.id===election.id);
    assert.equal(election.districts.length,verified.rows,election.id);
    assert.equal(election.districts.reduce((n,row)=>n+row.candidates.length,0),verified.candidatesChecked,election.id);
    for(const row of election.districts){
      const label=election.id+' / '+row.name;
      assert.equal(new Set(row.candidates.map(c=>c.name)).size,row.candidates.length,label+' duplicate candidate/ticket');
      assert.ok(row.candidates.every(c=>Number.isSafeInteger(c.votes)&&c.votes>=0),label);
      assert.equal(sum(row.candidates,'votes'),row.validVotes,label+' complete valid votes');
      assert.equal(row.validVotes+row.invalidVotes,row.votesCast,label+' ballots cast');
      assert.ok(row.votesCast<=row.eligibleVoters,label+' eligible voters');
      assert.equal(row.turnout,round2(100*row.votesCast/row.eligibleVoters),label+' turnout');
      for(const candidate of row.candidates){
        const expected=verified.percentageRule==='truncated2'
          ?Math.floor(candidate.votes*10000/row.validVotes)/100
          :round2(100*candidate.votes/row.validVotes);
        assert.equal(candidate.share,expected,label+' / '+candidate.name+' share of all valid votes');
      }
      const ranked=[...row.candidates].sort((a,b)=>b.votes-a.votes);
      assert.equal(row.districtLeader,ranked[0].name,label+' local leader');
      assert.equal(row.marginVotes,ranked[0].votes-ranked[1].votes,label+' leading margin');
      assert.ok(Math.abs(row.marginPoints-100*row.marginVotes/row.validVotes)<0.000051,label+' margin denominator');
    }
  }
});

test('Taipei current-affairs notes distinguish the new poll from debate expectations and appeal status',()=>{
  assert.match(page,/ELECTION WATCH \/ UPDATED 2026\.10\.21/);
  assert.match(page,/沈伯洋 50\.3%、蒋万安 33\.3%/);
  assert.match(page,/TVBS 10 月 3、5—7 日市话调查为蒋万安 49%、沈伯洋 41%/);
  assert.match(page,/TVBS 民调中心 10 月 20 日另发声明/);
  assert.match(page,/不能单凭这组差异判定信民结果无效/);
  assert.match(page,/不是投票支持度/);
  assert.match(page,/案件尚未终局/);
  assert.match(page,/不等于刑事二审无罪或推翻一审判决/);
  assert.match(page,/不据此推断现任市长或本届其他候选人的责任/);
});

test('Twelve-district charts use dated comparable fields and retain all districts',()=>{
  const charts=Guide.districtChartSeries(D);
  assert.deepEqual(charts.map(x=>x.id),['population','elderly','income','mayor-margin']);
  for(const chart of charts){
    assert.equal(chart.rows.length,12,chart.id);
    assert.equal(chart.rows[0].width,100,chart.id+' largest bar');
    assert.deepEqual(chart.rows.map(x=>x.value),[...chart.rows.map(x=>x.value)].sort((a,b)=>b-a),chart.id+' rank order');
  }
  const colorByDistrict=new Map(charts[0].rows.map(row=>[row.districtId,row.color]));
  assert.equal(new Set(colorByDistrict.values()).size,12,'every district has its own color');
  for(const chart of charts)for(const row of chart.rows)assert.equal(row.color,colorByDistrict.get(row.districtId),chart.id+' reuses district color');
  assert.equal(charts[0].period,'2026.09');
  assert.equal(charts[1].source[0],'age');
  assert.equal(charts[2].period,'2023');
  assert.equal(charts[3].period,'2022');
  assert.match(charts[3].sourceUrl,/db\.cec\.gov\.tw/);
  assert.ok(charts[3].rows.some(x=>x.name==='大同'&&x.detail.startsWith('陳時中')));
  assert.match(page,/id="district-charts"/);
  assert.match(page,/id="district-color-legend"/);
  assert.match(page,/id="district-chart-grid"/);
});

test('city comparisons match separately retrieved official totals and weight turnout by voters',()=>{
  for(const election of D.elections){
    const verified=audit.elections.find(e=>e.id===election.id);
    const totals=Object.fromEntries(fields.map(key=>[key,sum(election.districts,key)]));
    assert.deepEqual(totals,verified.cityTotals,election.id+' official city totals');
    if(election.geography!=='administrativeDistrict')continue;
    const before=structuredClone(election),city=Guide.aggregateElection(election);
    for(const key of fields)assert.equal(city[key],verified.cityTotals[key],election.id+' / '+key);
    assert.equal(round2(city.turnout),verified.cityTurnout,election.id+' official turnout');
    assert.equal(city.turnout,100*verified.cityTotals.votesCast/verified.cityTotals.eligibleVoters);
    assert.equal(sum(city.candidates,'votes'),verified.cityTotals.validVotes,election.id+' complete city votes');
    for(const candidate of city.candidates){
      assert.equal(candidate.share,100*candidate.votes/verified.cityTotals.validVotes,election.id+' city share');
    }
    assert.deepEqual(election,before,'Aggregation must not change the district results on repeated renders');
  }
  const legislative=D.elections.find(e=>e.type==='legislator');
  assert.throws(()=>Guide.aggregateElection(legislative),/administrative-district/);
});

test('all twelve administrative districts resolve to their eight complete legislative constituencies',()=>{
  assert.deepEqual(sorted(D.districts.map(d=>d.name)),sorted(Object.keys(legislativeMapping)));
  assert.equal(new Set(D.districts.map(d=>d.id)).size,12);
  assert.deepEqual(D.legislativeBoundaries.map(b=>b.id).sort((a,b)=>a-b),[1,2,3,4,5,6,7,8]);
  for(const [name,expected] of Object.entries(legislativeMapping)){
    assert.deepEqual(Guide.constituenciesForDistrict(D.legislativeBoundaries,name).map(b=>b.id).sort((a,b)=>a-b),expected,name);
  }
  assert.deepEqual(Guide.constituenciesForDistrict(D.legislativeBoundaries,'不存在的區'),[]);
  for(const election of D.elections.filter(e=>e.geography==='administrativeDistrict')){
    assert.deepEqual(sorted(election.districts.map(d=>d.name)),sorted(Object.keys(legislativeMapping)),election.id);
  }
  const legislative=D.elections.find(e=>e.type==='legislator');
  assert.equal(legislative.geography,'legislativeConstituency');
  assert.deepEqual(legislative.districts.map(row=>Number(row.code)).sort((a,b)=>a-b),[1,2,3,4,5,6,7,8]);
  assert.deepEqual(D.legislators.map(p=>p.constituency).sort((a,b)=>a-b),[1,2,3,4,5,6,7,8]);
  for(const verified of audit.incumbents){
    const person=D.legislators.find(p=>p.constituency===verified.constituency);
    const result=legislative.districts.find(row=>Number(row.code)===verified.constituency);
    assert.equal(person.name,verified.name);
    assert.equal(person.party,verified.party);
    assert.equal(result.candidates.find(c=>c.officialElected).name,person.name);
  }
});

test('Shilin, Songshan and Zhongzheng village partitions are complete and disjoint',()=>{
  const expected={'士林區':[[1,13],[2,38]],'松山區':[[3,20],[7,13]],'中正區':[[5,21],[8,10]]};
  const parts=D.legislativeBoundaries.flatMap(b=>b.partialDistricts.map(p=>({...p,constituency:b.id})));
  assert.deepEqual(sorted(new Set(parts.map(p=>p.district))),sorted(Object.keys(expected)));
  const full=D.legislativeBoundaries.flatMap(b=>b.fullDistricts);
  assert.equal(full.length,9);
  assert.equal(new Set(full).size,9);
  for(const [name,counts] of Object.entries(expected)){
    const rows=parts.filter(p=>p.district===name).sort((a,b)=>a.constituency-b.constituency);
    assert.deepEqual(rows.map(p=>[p.constituency,p.villages.length]),counts,name+' split counts');
    const villages=rows.flatMap(p=>p.villages);
    assert.equal(new Set(villages).size,villages.length,name+' duplicated village');
    assert.ok(villages.every(name=>typeof name==='string'&&name.endsWith('里')));
    assert.equal(villages.length,D.districts.find(d=>d.name===name).demographics.villages,name+' complete district');
    assert.ok(!full.includes(name),name+' must not also be assigned as a whole district');
  }
});

test('2026 council snapshot preserves 98 registrations and excludes the one known disqualification from 97 records',()=>{
  const council=D.council,groups=[...council.councilGroups].sort((a,b)=>a.id-b.id);
  const candidates=groups.flatMap(g=>g.candidates);
  const excluded=candidates.filter(c=>c.eligibilityStatus.startsWith('disqualified'));
  assert.equal(candidates.length,98);
  assert.equal(council.registrationCount,98);
  assert.equal(council.afterEligibilityReviewCount,97);
  assert.deepEqual(excluded.map(c=>[c.councilDistrict,c.name]),[[6,'游智彬']]);
  assert.equal(candidates.length-excluded.length,council.afterEligibilityReviewCount);
  assert.deepEqual(groups.map(g=>g.registeredCount),[20,13,13,14,14,19,2,3]);
  assert.deepEqual(groups.map(g=>g.afterEligibilityReviewCount),[20,13,13,14,14,18,2,3]);
  for(const group of groups){
    const removed=group.candidates.filter(c=>c.eligibilityStatus.startsWith('disqualified'));
    assert.equal(group.candidates.length,group.registeredCount,group.name);
    assert.equal(removed.length,group.knownDisqualifiedCount,group.name);
    assert.equal(group.candidates.length-removed.length,group.afterEligibilityReviewCount,group.name);
    assert.ok(group.candidates.every(c=>c.councilDistrict===group.id),group.name+' candidate assignment');
  }
  assert.equal(council.registrationSequenceIsNotBallotNumber,true);
  assert.ok(candidates.every(c=>c.ballotNumber===null),'Registration order must not become a ballot number before the draw');
});

test('six regional council constituencies cover twelve districts and retain the published 59 plus 2 seats',()=>{
  const expected=[['北投區','士林區'],['內湖區','南港區'],['松山區','信義區'],['中山區','大同區'],['中正區','萬華區'],['大安區','文山區']];
  const regional=D.council.councilGroups.filter(g=>g.type==='regional').sort((a,b)=>a.id-b.id);
  const indigenous=D.council.councilGroups.filter(g=>g.type==='indigenous').sort((a,b)=>a.id-b.id);
  assert.deepEqual(regional.map(g=>g.id),[1,2,3,4,5,6]);
  assert.deepEqual(regional.map(g=>sorted(g.districts)),expected.map(sorted));
  assert.deepEqual(regional.map(g=>g.seats2026),[12,9,9,8,8,13]);
  assert.deepEqual(regional.map(g=>D.councilConstituencies.find(c=>c.id===g.id).reservedWomenSeats),[3,2,2,2,2,3]);
  assert.deepEqual(sorted(regional.flatMap(g=>g.districts)),sorted(Object.keys(legislativeMapping)));
  assert.equal(sum(regional,'seats2026'),59);
  assert.deepEqual(indigenous.map(g=>[g.id,g.seats2026]),[[7,1],[8,1]]);
  assert.equal(D.council.regionalCouncilSeats,59);
  assert.equal(D.council.indigenousCouncilSeats,2);
  assert.equal(D.council.councilSeatTotal,61);
  assert.equal(sum(D.council.councilGroups,'seats2026'),61);
});

test('invalid URL parameters fall back safely and legislative results cannot enter administrative comparisons',()=>{
  const expected={district:'zhongshan',election:'cec-C1-00-2022',peer:'neihu',compare:'city',mapMode:'district'};
  assert.deepEqual(Guide.readRoute('/taipei.html',D),expected);
  assert.deepEqual(Guide.readRoute('/taipei.html?district=missing&election=missing&peer=missing&compare=missing&layer=missing',D),expected);
  const legislative=D.elections.find(e=>e.type==='legislator');
  assert.deepEqual(Guide.readRoute('/taipei.html?election='+legislative.id,D),expected);
  assert.deepEqual(Guide.readRoute('/taipei.html?district=songshan&election=cec-C1-00-2014&peer=daan&compare=wanhua&layer=age',D),{
    district:'songshan',election:'cec-C1-00-2014',peer:'daan',compare:'wanhua',mapMode:'age'
  });
});

test('both URL comparison controls reject the selected district across all twelve districts',()=>{
  for(const district of D.districts){
    const route=Guide.readRoute('/taipei.html?district='+district.id+'&peer='+district.id+'&compare='+district.id,D);
    assert.equal(route.district,district.id);
    assert.notEqual(route.peer,district.id,district.id+' profile comparison');
    assert.ok(D.districts.some(d=>d.id===route.peer));
    assert.equal(route.compare,'city',district.id+' ballot comparison');
  }
  assert.equal(Guide.readRoute('/taipei.html?district=neihu&peer=neihu',D).peer,'wanhua');
});
